  /* Cheat codes. Only a SHA-256 fingerprint of each code is stored here, never the code itself.
     Codes are not case-sensitive. Each one works once per Tornies save. */
  const CHEATS = { '757ec2a6bba2f2b62ae16465ef99cff4394de5181c0639dd5e8c70963eb609df': { id: 'bars5', item: 'energy_bar', n: 5, msg: '5 Energy Bars added to your Tornies bag!' },
    '9e116eb4d45dd699c837170557f929d34edd6b962bc6d39406b289632ba6c992': { id: 'bars25', item: 'energy_bar', n: 25, msg: '25 Energy Bars added to your Tornies bag!' },
    '598f37575f34c5dae2c59a5582540925d28149d56009d8b2dec65cd3bf033fd4': { id: 'xp2', item: 'xp2', n: 3600, msg: 'Double XP is on for the next hour of Tornies play!' },
    '86f139d3a33bf512232d065ea7cced4cb21d6b6e53b692cdc1386ac03bebcbec': { id: 'bars50', item: 'energy_bar', n: 50, msg: '50 Energy Bars added to your Tornies bag! With the dash.' } };
  async function sha256(text) {
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
    return Array.prototype.map.call(new Uint8Array(buf), function (b) { return ('0' + b.toString(16)).slice(-2); }).join('');
  }
  async function tryCheat() {
    const input = $(settingsBox, '.ta-cheatin:not(.ta-keyin)'), msg = $(settingsBox, '.ta-cheatmsg');
    if (!input) return;
    const raw = input.value.trim(), code = raw.toLowerCase();
    input.value = '';
    if (!code) return;
    // Signed gift codes from the developer (checked inside Tornies with the developer's public key).
    if (/^gift-/i.test(raw) && games.pocket && games.pocket.gift) {
      msg.textContent = 'Checking gift code…';
      const g = await games.pocket.gift(raw);
      msg.textContent = g.msg; if (g.ok) sfx.win(); else sfx.miss();
      return;
    }
    let h = '';
    try { h = await sha256(code); } catch (e) {}
    const c = CHEATS[h];
    if (!c) { msg.textContent = 'Nothing happens.'; sfx.miss(); return; }
    const r = games.pocket && games.pocket.redeem ? games.pocket.redeem('cheat_' + c.id, c.item, c.n) : 'nosave';
    if (r === 'nosave') { msg.textContent = 'Start a Tornies adventure first.'; sfx.miss(); return; }
    if (r === 'used') { msg.textContent = 'That code has already been used on this save.'; sfx.miss(); return; }
    msg.textContent = c.msg; sfx.win();
  }
