  const tweens = [];
  function tween(dur, fn) { return new Promise(function (res) { tweens.push({ t: 0, dur: Math.max(0.001, dur), fn: fn, res: res }); }); }
  function wait(s) { return tween(s, function () {}); }
  function updateTweens(dt) {
    tweens.slice().forEach(function (t) {
      t.t += dt; const k = Math.min(1, t.t / t.dur); t.fn(k);
      if (k >= 1) { tweens.splice(tweens.indexOf(t), 1); t.res(); }
    });
  }
  function fadeOut(d) { return tween(d || 0.2, function (k) { fade = k; }); }
  // Before fading in, wait (screen still dark, up to about a second) while a newly entered map draws what is on
  // screen. On a slow device the loading bar then shows.
  async function fadeIn(d) {
    for (let n = 0; n < 30 && typeof iwIsLoading === 'function' && iwIsLoading() && scene === worldScene; n++) await wait(0.03);
    return tween(d || 0.2, function (k) { fade = 1 - k; });
  }

  /* ---------- Modals: dialog boxes and menus ---------- */
  function push(m) { modals.push(m); }
  function pop(m) { const i = modals.indexOf(m); if (i >= 0) modals.splice(i, 1); }
  function closeModal(m) { pop(m); }
  function textCps() { return [32, 64, 150][G && G.opts ? G.opts.speed : 1]; }
  function drawTextBox(lines, ch, arrow, t) {
    box(2, VH - 46, VW - 4, 44);
    let left = Math.floor(ch);
    lines.forEach(function (l, i) {
      const s = l.slice(0, Math.max(0, left)); left -= l.length;
      text(s, 11, VH - 39 + i * 15, '#303846', { sz: 9.5 });
    });
    if (arrow && Math.floor(t * 3) % 2 === 0) { ctx.fillStyle = '#e05040'; ctx.beginPath(); ctx.moveTo(VW - 18, VH - 14); ctx.lineTo(VW - 12, VH - 14); ctx.lineTo(VW - 15, VH - 10); ctx.closePath(); ctx.fill(); }
  }
  function say(t, o) {
    o = o || {};
    return new Promise(function (res) {
      const pages = [];
      fillNames(t).split('|').forEach(function (seg) { const L = wrapText(seg, VW - 26, 9.5); for (let i = 0; i < L.length; i += 2) pages.push(L.slice(i, i + 2)); });
      const m = { kind: 'say', pages: pages, pi: 0, ch: 0, t: 0, done: false };
      const len = function () { return pages[m.pi].join('').length; };
      m.update = function (dt) {
        m.t += dt;
        if (m.ch < len()) m.ch = Math.min(len(), m.ch + dt * textCps());
        else if (o.hold && m.pi === pages.length - 1 && !m.done) { m.done = true; res(m); }
      };
      m.btn = function (b) {
        if (m.done || (b !== 'a' && b !== 'b')) return;
        if (m.ch < len()) { m.ch = len(); return; }
        if (m.pi < pages.length - 1) { m.pi++; m.ch = 0; blip(); return; }
        pop(m); res();
      };
      m.draw = function () { drawTextBox(pages[m.pi], m.ch, !m.done && m.ch >= len() && (!o.hold || m.pi < pages.length - 1), m.t); };
      push(m);
    });
  }
  // A list menu. Resolves with the chosen index, or -1 when cancelled with B.
  function menu(items, o) {
    o = o || {};
    return new Promise(function (res) {
      const sz = o.sz || 9, lh = o.lh || 14, cols = o.cols || 1, vis = o.visible || items.length;
      const label = function (it) { return typeof it === 'string' ? it : it.label; };
      const rowsN = Math.ceil(Math.min(items.length, vis * cols) / cols);
      let w = o.w || 0;
      const rightOf = function (it) { return typeof it.right === 'function' ? it.right() : it.right; };
      if (!w) { items.forEach(function (it) { const r = rightOf(it); w = Math.max(w, tw(label(it), sz) + (r ? tw(r, sz) + 12 : 0)); }); w = Math.ceil(w + 24); }
      const h = o.h || rowsN * lh + 10;
      const x = o.x !== undefined ? o.x : VW - w - 4, y = o.y !== undefined ? o.y : VH - 48 - h;
      const m = { kind: 'menu', items: items, i: Math.min(o.i || 0, items.length - 1), top: 0 };
      function moved() { if (m.i < m.top) m.top = m.i; if (m.i >= m.top + vis) m.top = m.i - vis + 1; blip(); if (o.onMove) o.onMove(m.i); }
      m.btn = function (b) {
        const n = items.length;
        if (b === 'up') { if (cols > 1) { if (m.i - cols >= 0) { m.i -= cols; moved(); } } else { m.i = (m.i + n - 1) % n; moved(); } }
        else if (b === 'down') { if (cols > 1) { if (m.i + cols < n) { m.i += cols; moved(); } } else { m.i = (m.i + 1) % n; moved(); } }
        else if (b === 'left' && cols > 1) { if (m.i % cols > 0) { m.i--; moved(); } }
        else if (b === 'right' && cols > 1) { if (m.i % cols < cols - 1 && m.i + 1 < n) { m.i++; moved(); } }
        else if (b === 'left' && o.onLeft) o.onLeft(m.i);
        else if (b === 'right' && o.onRight) o.onRight(m.i);
        else if (b === 'a') {
          const it = items[m.i];
          if (it && it.disabled) { tone(200, 0.08, 'square', 0.04); return; }
          sfx.click(); pop(m); res(m.i);
        } else if ((b === 'b' && o.cancel !== false) || (b === 'start' && o.start)) { blip(); pop(m); res(-1); }
      };
      m.draw = function () {
        if (o.drawBehind) o.drawBehind(m.i);
        box(x, y, w, h, o.style);
        const cw = (w - 8) / cols;
        for (let k = m.top * cols; k < Math.min(items.length, (m.top + vis) * cols); k++) {
          const r = Math.floor(k / cols) - m.top, c = k % cols, it = items[k];
          const ix = x + 6 + c * cw, iy = y + 6 + r * lh;
          const col = it.disabled ? '#a0a6b0' : (o.style === 'd' ? '#ffffff' : '#303846');
          text(label(it), ix + 8, iy + (lh - sz) / 2 - 0.5, col, { sz: sz, light: o.style === 'd' });
          if (it.right) text(rightOf(it), x + w - 9, iy + (lh - sz) / 2 - 0.5, col, { sz: sz, al: 'right' });
          if (k === m.i) cursor(ix + 1, iy + (lh - 7) / 2);
        }
        if (o.visible && items.length > vis) {
          if (m.top > 0) { ctx.fillStyle = '#e05040'; ctx.beginPath(); ctx.moveTo(x + w / 2 - 3, y + 4); ctx.lineTo(x + w / 2 + 3, y + 4); ctx.lineTo(x + w / 2, y + 1); ctx.fill(); }
          if (m.top + vis < items.length) { ctx.fillStyle = '#e05040'; ctx.beginPath(); ctx.moveTo(x + w / 2 - 3, y + h - 4); ctx.lineTo(x + w / 2 + 3, y + h - 4); ctx.lineTo(x + w / 2, y + h - 1); ctx.fill(); }
        }
        if (o.draw) o.draw(m.i);
      };
      push(m);
      if (o.onMove) o.onMove(m.i);
    });
  }
  async function ask(t, opts) {
    const d = await say(t, { hold: true });
    const i = await menu(opts, {});
    pop(d);
    return i;
  }
  async function yesno(t) { return (await ask(t, ['YES', 'NO'])) === 0; }
  // A frame showing a Tornie, used when choosing a starter.
  function showMon(n) {
    const m = { btn: function () {}, draw: function () { box(VW / 2 - 40, 8, 80, 80); ctx.drawImage(monSprite(n), VW / 2 - 32, 14, 64, 64); } };
    push(m); cry(n);
    return m;
  }
  // Text entry overlay (names and nicknames). Uses a real text box so phones get a keyboard.
  function askName(title, def, max) {
    return new Promise(function (res) {
      const lock = { btn: function () {} };
      push(lock);
      nameBox.innerHTML = '<form class="ta-pt-form"><b></b><input type="text" autocomplete="off" spellcheck="false"><button type="submit" class="ta-btn">OK</button></form>';
      const form = $(nameBox, 'form'), input = $(nameBox, 'input');
      $(form, 'b').textContent = title;
      input.maxLength = max; input.value = def;
      nameBox.hidden = false;
      setTimeout(function () { try { input.focus(); input.select(); } catch (e) {} }, 30);
      form.addEventListener('submit', function (e) {
        e.preventDefault();
        const v = input.value.replace(/[^A-Za-z0-9 .'\-]/g, '').trim().slice(0, max);
        nameBox.hidden = true; nameBox.innerHTML = ''; pop(lock); clearHeld();
        try { cv.focus({ preventScroll: true }); } catch (e2) {}
        res(v || def);
      });
    });
  }

