  /* ---------- Story scripts ---------- */
  async function profStop() {
    await say('???: Whoa, hold up! Not that way!');
    await say('PROF. QUINN: The long grass is crawling with wild Tornies. Walk in there alone and you\'ll end up in hospital.|Come to my lab first. It\'s the big building in the middle of town.');
    await walkPlayer(['down']);
  }
  async function momTalk() {
    if (!G.flags.starter) { await say('MOM: Morning, {P}! Prof. Quinn popped round looking for you.|Her lab is the big building in the middle of town. Off you go!'); return; }
    await say('MOM: {P}! You look worn out. Let your Tornies rest a while.');
    await healFlash(); healParty(); G.respawn = { map: 'home', x: 4, y: 5, dir: 'up' };
    await say('MOM: There! Your Tornies are full of energy again.|Take care out there, sweetie!');
  }
  async function sisterTalk() {
    if (!G.flags.sisterGift) {
      await say('SISTER: Hi {P}! My brother {R} ran off to Prof. Quinn\'s lab ages ago.|Oh! Take these. Out there you\'ll need them.');
      addItem('potion', 2); G.flags.sisterGift = 1; jingle('item');
      await say('{P} got 2 Small First Aid Kits!');
      return;
    }
    await say('SISTER: Tornie Clinics fix up your team for free. Look for the red roof with the heart!');
  }
  async function profTalk() {
    if (!G.flags.starter) { await say('PROF. QUINN: Ah, {P}! There you are.|Torn City is full of wild creatures called Tornies, and nobody should face them without a partner.|Three young Tornies are waiting on that table. Take your pick!'); return; }
    if (!G.flags.rival1) { await say('PROF. QUINN: Spend some time with your new partner, {P}. The more you fight side by side, the stronger you both get.'); return; }
    await say('PROF. QUINN: Head north through Route 1 to reach Westgate.|Fill in your Tornie Log as you go, and try your luck at the Westgate Arena.');
  }
  async function rivalLabTalk() {
    if (!G.flags.starter) { await say('{R}: Hurry up and pick, {P}! Prof. Quinn said you get first pick.|Doesn\'t matter. Whatever you pick, I\'ll pick something better!'); return; }
    await say('{R}: My ' + SP[G.flags.rivalMon].name + ' looks way stronger than yours.');
  }
  async function pickStarter(n) {
    if (G.flags.starter) { await say('That one belongs to the lab now.'); return; }
    const pop = showMon(n);
    const yes = await yesno('PROF. QUINN: ' + SP[n].name + ', the ' + SP[n].types[0] + ' type. Is this the one?');
    closeModal(pop);
    if (!yes) return;
    G.flags.starter = n; G.flags['took' + n] = 1; removeNpc('cap' + n);
    await say('PROF. QUINN: Great pick! ' + SP[n].name + ' has taken a shine to you already.');
    const mon = makeMon(n, 5);
    jingle('get'); await say(SP[n].name + ' joined {P}\'s team!');
    await offerNickname(mon);
    addMon(mon, true);
    const rv = { 1: 4, 4: 7, 7: 1 }[n];
    G.flags.rivalMon = rv;
    const rival = npcById('rival'); if (rival) faceTo(rival, 'up');
    await say('{R}: Then I\'ll take this one! Nobody beats me and my ' + SP[rv].name + '!');
    G.flags['took' + rv] = 1; removeNpc('cap' + rv);
    jingle('get'); await say(SP[rv].name + ' joined {R}\'s team!');
  }
  async function rivalLabBattle() {
    const rival = npcById('rival');
    if (rival) faceTo(rival, rival.y < W.p.y ? 'down' : 'up');
    await say('{R}: Wait up, {P}! Let\'s see whose Tornie is tougher. Battle me!');
    const res = await trainerBattle('rival1', { noBlackout: true, party: [[G.flags.rivalMon, 5]] });
    healParty();
    if (res === 'win') await say('{R}: Ugh, beginner\'s luck! We\'re going to train until we\'re unbeatable!');
    else await say('{R}: Ha! Told you mine was better! See you around!');
    await say('{R}: I\'m heading to Westgate. Try to keep up, {P}!');
    G.flags.rival1 = 1; removeNpc('rival'); sfx.click();
    await say('PROF. QUINN: Wait, {P}! You\'ll need these.');
    G.flags.dex = 1; jingle('get');
    await say('{P} got a TORNIE LOG!|It keeps a record of every Tornie you meet and catch.');
    addItem('capsule', 5); jingle('item');
    await say('{P} got 5 Capsules!|Throw one at a worn-out wild Tornie to bring it on board.');
    addItem('potion', 3); jingle('item');
    await say('{P} got 3 Small First Aid Kits!|Use one in battle to patch up a Tornie by 20 HP.');
    await say('PROF. QUINN: There are 171 kinds of Tornies out there. Let\'s see how many you can find, {P}!');
    saveGame();
  }
  async function nurseTalk() {
    const c = await ask('NURSE: Hi there! Rough day out there? I can patch your team up for free.', ['Yes please', 'No thanks']);
    if (c !== 0) { await say('NURSE: No problem. Stay safe out there!'); return; }
    await say('NURSE: Pop them on the machine for me...');
    await healFlash(true); healParty();
    G.respawn = { map: W.map.id, x: 4, y: 4, dir: 'up' };
    await say('NURSE: All done! Your team is fighting fit again.|Try not to end up back here too soon!');
  }
  async function brickTalk(npc) {
    if (G.badges.indexOf('brick') >= 0) { await say('BRICK: The road north opens soon. Midtown\'s Arena Leader won\'t go easy on you!'); return; }
    await say('BRICK: So you\'re the new trainer on the block.|I\'m Brick, and this is my Arena. My Tornies are tough as bricks and twice as stubborn.|Let\'s see if you can knock down my wall!');
    const r = await trainerBattle('brick', { npc: npc });
    if (r !== 'win') return;
    await say('BRICK: Fair\'s fair. You knocked my wall down. This is yours.');
    G.badges.push('brick'); jingle('badge');
    await say('{P} was awarded the BRICK MEDAL!');
    addItem('disc_rock_tomb', 1); jingle('item');
    await say('BRICK: And a Training Disc for Rubble Trap. Rocks everywhere, just like my Arena. Pick the right Tornie, it only works once.|{P} got Disc: Rubble Trap!');
    await fieldDiscGift('brick', 'BRICK');
    await say('BRICK: Seven more Arena Leaders run the other districts.|Win all eight medals and the Torn Council will want a word with you. Go get \'em, champ!');
    saveGame();
  }
  async function guideTalk() {
    if (G.badges.indexOf('brick') >= 0) { await say('You beat Brick! That was rock solid, champ!'); return; }
    await say('Psst! Brick fights with Stone and Earth Tornies.|Water and Plant moves hit them hard, and Brawl moves work well too.|Electric moves just fizzle out, so don\'t bother.');
  }

