  // Small helper for drawing city maps in code.
  function canvasMap(w, h, fill) {
    const a = []; for (let y = 0; y < h; y++) a.push(new Array(w).fill(fill));
    const o = {
      fill: function (x, y, ww, hh, c) { for (let j = y; j < y + hh; j++) for (let i = x; i < x + ww; i++) if (a[j] && i >= 0 && i < w) a[j][i] = c; return o; },
      put: function (pts, c) { pts.forEach(function (p) { if (a[p[1]]) a[p[1]][p[0]] = c; }); return o; },
      rows: function () { return a.map(function (r) { return r.join(''); }); }
    };
    return o;
  }
  function rivalLine() { return { 1: [1, 2, 3], 4: [4, 5, 6], 7: [7, 8, 9] }[G.flags.rivalMon || 4]; }
  function phoneMsg(from, text) { tone(1320, 0.06, 'square', 0.03); setTimeout(function () { tone(1760, 0.08, 'square', 0.03); }, 90); return say('Your TornPhone buzzes. A message from ' + from + ':|' + text); }

