  async function slotMachine(x, y) {
    if (G.money < 100) { await say('A slot machine. $100 a pull. You can\'t afford it.'); return; }
    if (!(await yesno('A slot machine! Pull the lever for $100?'))) return;
    G.money -= 100;
    const sym = ['7', 'CHERRY', 'BAR', 'BELL', 'TORN'];
    const lucky = x === 14 && y === 7 && isNight() && !G.flags.slot777;
    let r;
    if (lucky) r = [0, 0, 0];
    else r = [0, 1, 2].map(function () { return Math.floor(Math.random() * sym.length); });
    for (let k = 0; k < 6; k++) { tone(500 + k * 80, 0.05, 'square', 0.03); await wait(0.08); }
    await say('[ ' + r.map(function (i) { return sym[i]; }).join(' | ') + ' ]');
    if (lucky) {
      G.flags.slot777 = 1; jingle('badge'); G.money += 7777; addItem('energy_bar', 1);
      await say('THREE SEVENS! The lucky machine! Lights flash, sirens wail!|{P} won $7,777 and an Energy Bar!');
    } else if (r[0] === r[1] && r[1] === r[2]) { jingle('item'); G.money += 1500; await say('Jackpot! {P} won $1,500!'); }
    else if (r[0] === r[1] || r[1] === r[2] || r[0] === r[2]) { jingle('item'); G.money += 200; await say('Two of a kind! {P} won $200.'); }
    else await say('Nothing. The machine makes a sad little noise.');
    saveGame();
  }
