  async function hqLift() {
    if (G.flags.hqPass) { await say('The lift doors slide open.'); warpTo('hq2', 7, 9, 'up'); return; }
    await say('A lift with a keypad. A sign reads: ENTER PASSWORD.');
    const p = (await askName('PASSWORD', '', 12)).toUpperCase().replace(/\s+/g, '');
    if (p === 'BAZAAR') {
      seq([[0, 880, 0.08, 'square', 0.04], [90, 1320, 0.12, 'square', 0.04]]);
      G.flags.hqPass = 1; await say('*Beep!* ACCESS GRANTED.|The lift doors slide open.'); warpTo('hq2', 7, 9, 'up');
    } else { tone(160, 0.3, 'square', 0.04); await say('*Bzzt!* ACCESS DENIED.|Maybe one of the Racket thugs knows the password.'); }
  }
  async function mimicCrate() {
    await say('One of the crates is breathing.|...Crates aren\'t supposed to breathe.');
    if (!(await yesno('Open the crate?'))) return;
    await say('The crate has TEETH!');
    const mon = makeMon(96, 38);
    if (Math.random() < rankedOdds()) mon.rk = 1;
    G.flags.mimic = 1;
    const r = await battle({ wild: mon });
    if (r === 'lose') await blackout();
    saveGame();
  }
