  async function vaultDoor() {
    if (!G.bag.vaultkey) { await say('A massive vault door. A sign says: VAULT CLOSED TO THE PUBLIC.'); return; }
    if (G.flags.vault && !hasMedals(8)) { await say('The vault door is shut tight. The Torn Council have put three new locks on it.|A plaque reads: "Only a champion may pass."'); return; }
    await say('{P} turns the Vault Key. Gears grind, bolts slide...|The huge door swings open!');
    seq([[0, 120, 0.4, 'sawtooth', 0.05, 60], [400, 80, 0.4, 'sawtooth', 0.05, 50]]);
    warpTo('vault', 5, 10, 'up');
  }
