  async function pennyTalk(n) {
    await say('Nurse Penny is standing perfectly still, staring at the wall.|A huge shadow looms behind her!');
    await say('PENNY: ...the patients... need... their rest...');
    const mon = makeMon(83, 40);
    const r = await battle({ wild: mon });
    if (r === 'lose') { await blackout(); return; }
    if (r === 'run') { await say('The shadow is still hanging over Penny...'); return; }
    await say('The shadow fades. Penny blinks and looks around.');
    await say('PENNY: Wh... where am I? The last thing I remember is opening a filing cabinet...|You saved me? Oh, you lovely thing. Let\'s get out of here, it\'s FREEZING.');
    await fadeOut(0.3); removeNpc('penny'); G.flags.ward = 1; await fadeIn(0.3);
    await say('Penny hurried back downstairs.|...Something in the dark at the end of the ward is still watching. Maybe it only comes out at night.');
    saveGame();
  }
  async function lilyTalk(n) {
    const has = G.party.some(function (m) { return m.sp === 81 || m.sp === 82; });
    if (!has) { await say('A pale young woman is sitting on the end of a bed.|LILY: I lost my friend. A little ghost. It used to float round the beds and make everyone laugh.|Have you seen it? If you find one like it, will you bring it to me?'); return; }
    await say('LILY: Oh! You found one! It\'s just like my friend!|Hello, little one. Hello...');
    await say('LILY: Thank you. I think I can go home now.|Here. I kept this safe for a long, long time.');
    addItem('disc_phantom_rush', 1); jingle('get');
    await say('{P} got a Disc: Phantom Rush!');
    await fadeOut(0.6); G.flags.lily = 1; removeNpc('lily'); await fadeIn(0.6);
    await say('Lily is gone. There\'s a faint smell of flowers in the air.');
    saveGame();
  }
