  async function towerDesk() {
    await say('RECEPTIONIST: Welcome to the Council Tower.|Upstairs, the four members of the Torn Council are waiting. You must beat all four in a row, then the Champion.');
    await say('RECEPTIONIST: Once you go up, there\'s no coming back down until you win or your team is hospitalized.|You can still use items between battles. Are you ready?');
    if (!(await yesno('Climb the Council Tower?'))) { await say('RECEPTIONIST: Take your time. The Clinic outside will patch up your team.'); return; }
    G.cRun = 0; saveGame();
    await fadeOut(0.4); loadMap('council1', 4, 10, 'up'); await fadeIn(0.4);
  }
  const COUNCIL = [
    { map: 'council1', id: 'bogie', name: 'BOGIE', floor: 'M', next: 'council2',
      hi: 'Hey. I\'m bogie. Welcome to the Torn Council.|Shadow Tornies are a lot like a good mugging. You never see them coming, and you always feel it afterwards.',
      bye: 'Not bad at all. CloudJumper\'s next. Watch out, he\'s been testing new strategies all week.' },
    { map: 'council2', id: 'cloud', name: 'CLOUDJUMPER', floor: 'G', next: 'council3',
      hi: 'Oh, hi! I\'m CloudJumper. I spend most of my time hunting bugs.|Then I catch them, and train them, and now they\'re really, REALLY strong. Let\'s go!',
      bye: 'That was awesome. PrincessJulie is through the door. Be polite, she likes that.' },
    { map: 'council3', id: 'julie', name: 'PRINCESSJULIE', floor: 'J', next: 'council4',
      hi: 'Welcome to my court, little trainer. I am PrincessJulie.|My Tornies are cold, clever and impeccably groomed. I do hope you\'re not going to embarrass yourself.',
      bye: 'Delightful. Truly. Jack-o awaits. Do try not to scream.' },
    { map: 'council4', id: 'jacko', name: 'JACK-O', floor: 'W', next: 'champion',
      hi: 'BOO! Ha! Got you. I\'m Jack-o, last of the Torn Council.|Every day is Halloween in here. My Tornies love a good scare. Do YOU?',
      bye: 'Spooktacular! Okay, okay, no more puns. Chedburn is through that last door.|Go on. He\'s been looking forward to this since the day you got your first medal.' }
  ];
  COUNCIL.forEach(function (c, i) {
    const F = c.floor;
    const rows = ['wwwwwwwwww', 'wwwwwwwwww', 'xFFFZZFFFx', 'FFFFFFFFFF', 'FFFFFFFFFF', 'xFFFFFFFFx', 'FFFFFFFFFF', 'FFFFFFFFFF', 'xFFFFFFFFx', 'FFFFFFFFFF', 'FFFFFFFFFF', 'FFFFFFFFFF'].map(function (r) { return r.replace(/F/g, F); });
    defMap(c.map, {
      name: 'Council Tower ' + (i + 1) + 'F', bg: 'council', border: 'w', indoor: true, tiles: F, dark: c.id === 'bogie' || c.id === 'jacko', banner: 1,
      rows: rows,
      statue: function () { return 'A statue of ' + c.name.charAt(0) + c.name.slice(1).toLowerCase() + '\'s favourite Tornie.'; },
      acts: [[4, 2, councilDoor(i)], [5, 2, councilDoor(i)]],
      npcs: [{ id: 'cm_' + c.id, x: 4, y: 4, dir: 'down', pal: c.id, move: 'still', run: function (n) { return councilTalk(i, n); } }]
    });
  });
  function councilDoor(i) {
    return async function () {
      if ((G.cRun || 0) <= i) { await say('The door is sealed tight. A sign reads: DEFEAT THE COUNCIL MEMBER TO PROCEED.'); return; }
      await say('The door slides open...');
      await fadeOut(0.4); loadMap(COUNCIL[i].next, 4, 10, 'up'); await fadeIn(0.4);
    };
  }
  async function councilTalk(i, n) {
    const c = COUNCIL[i];
    if ((G.cRun || 0) > i) { await say(c.name + ': ' + c.bye); return; }
    await say(c.name + ': ' + c.hi);
    const r = await trainerBattle(c.id, { noBlackout: true, party: rematchParty(c.id) });
    if (r !== 'win') { G.cRun = 0; await blackout(); return; }
    G.cRun = i + 1;
    await say(c.name + ': ' + c.bye);
    saveGame();
  }
  defMap('champion', {
    name: 'Champion\'s Hall', bg: 'council', border: 'w', indoor: true, tiles: 'Y', banner: 1,
    rows: ['wwwwwwwwww', 'wwwwwwwwww', 'gYYYBBYYYg', 'YYYYYYYYYY', 'YYYYYYYYYY', 'xYYYYYYYYx', 'YYYYYYYYYY', 'YYYYYYYYYY', 'xYYYYYYYYx', 'YYYYYYYYYY', 'YYYYYYYYYY', 'YYYYYYYYYY'],
    things: { B: 'Chedburn\'s bookshelf. "Building a City From Scratch", "Tornies: A Field Guide" and, oddly, "Coding for Dummies".' },
    npcs: [
      { id: 'cm_ched', x: 4, y: 4, dir: 'down', pal: 'chedburn', move: 'still', cond: function () { return !G.flags.champion; }, run: chedburnFinal },
      { id: 'cm_ched2', x: 4, y: 4, dir: 'down', pal: 'chedburn', move: 'still', cond: function () { return !!G.flags.champion; }, run: chedburnAfter }
    ]
  });
  async function chedburnFinal(n) {
    if ((G.cRun || 0) < 4) { await say('CHEDBURN: Ah, {P}. You\'ll need to beat the whole Council first. Rules are rules, even for me.'); return; }
    await say('CHEDBURN: {P}. You made it.|I remember the day Prof. Quinn told me a rookie from Maple Hollow had picked up a Tornie for the first time.');
    await say('CHEDBURN: Since then you\'ve beaten eight Arena Leaders. You brought down the Racket. You stood next to me in that vault while Lockheart woke up.|You\'ve seen more of Torn City than most people who\'ve lived here their whole lives.');
    await say('CHEDBURN: I built this city a long time ago. I\'ve been its Champion ever since.|Nobody has beaten me. Not once. I\'d very much like you to be the first.');
    await say('CHEDBURN: No holding back now. Show me everything!');
    const r = await trainerBattle('chedburn', { noBlackout: true });
    if (r !== 'win') { G.cRun = 0; await say('CHEDBURN: A fine battle. Come back stronger. I\'ll be right here.'); await blackout(); return; }
    await say('CHEDBURN: ...');
    await say('CHEDBURN: Ha! Ha ha ha! I lost! I actually lost!|Do you know how long I\'ve waited to say that? Congratulations, {P}. You are the new Champion of Torn City!');
    await say('CHEDBURN: There\'s one more thing. When we founded the Tornie League, TornTech made a single capsule. Just one, ever.|A capsule so strong that nothing can escape it. I\'ve kept it for years, waiting for a worthy Champion.');
    addItem('federal', 1); jingle('badge');
    await say('{P} received the FEDERAL CAPSULE!|It never fails. There will only ever be one. Use it wisely!');
    await say('CHEDBURN: Now, come with me. Every Champion\'s team goes into the Hall of Fame.');
    G.flags.champion = 1; G.cRun = 0;
    G.hof = (G.hof || []).concat([{ name: G.name, team: G.party.map(function (m) { return [m.sp, m.lv, m.nick || '', m.rk ? 1 : 0]; }) }]);
    await fadeOut(0.6);
    await hallOfFame();
    G.respawn = { map: 'maple', x: 9, y: 13, dir: 'down' };
    loadMap('maple', 9, 13, 'down');
    healParty(); saveGame();
    await fadeIn(0.6);
    await say('MOM: {P}! I watched the whole thing on TV! That\'s my {P}, the Champion of Torn City!|Prof. Quinn called. She says there are still Tornies out there nobody has ever seen. Legends, she called them.');
    await phoneMsg('Chedburn', 'Congratulations again, Champion. Torn City is full of secrets, and now they\'re all open to you.|The furnace, the power station, the frozen cave, the bank vault... and something at the end of the Docks pier. Go and see.');
  }
  // After the first win, the Council and Chedburn rebuild their teams 12 levels stronger.
  function rematchParty(id) { return G.flags.champion ? TRAINERS[id].party.map(function (q) { return [q[0], Math.min(100, q[1] + 12)]; }) : undefined; }
  async function chedburnAfter(n) {
    if ((G.cRun || 0) < 4) { await say('CHEDBURN: Champion! Back for a visit?|My door\'s always open. Well, after you\'ve beaten the Council again, of course. Rules are rules.'); return; }
    await say('CHEDBURN: Back again, and through the whole Council! I\'ve been training too, you know.|Let\'s see who the real Champion is. No mercy this time!');
    const r = await trainerBattle('chedburn', { noBlackout: true, party: rematchParty('chedburn') });
    G.cRun = 0;
    if (r !== 'win') { await say('CHEDBURN: Ha! The old man\'s still got it. Come back any time.'); await blackout(); return; }
    await say('CHEDBURN: Magnificent. You\'re the Champion through and through.');
    G.money += 20000; jingle('item'); await say('{P} got a $20,000 Champion\'s purse!');
    if (G.flags.caught121) { saveGame(); return; }
    await say('CHEDBURN: ...There\'s someone here who wants to meet you. Someone very old.|Before there was a Torn City, before there was a Tornie League, there was this little fellow.');
    cry(121);
    await say('A Tornie made of glowing crystal steps out from behind Chedburn\'s chair!|CHEDBURN: This is Genesite. The very first Tornie. It woke up beside the Origin Shard, a long, long time ago.');
    await say('CHEDBURN: It\'s been by my side ever since. But it\'s been watching you, {P}. I think it wants to see the world.|If you can win its trust, it\'s yours. Go on!');
    await say('CHEDBURN: Here, let me patch your team up first. It wouldn\'t be a fair fight otherwise.'); healParty(); await healFlash(false);
    const mon = makeMon(121, 70);
    if (Math.random() < rankedOdds()) mon.rk = 1;
    const b = await battle({ wild: mon, legend: true });
    if (b === 'caught') { G.flags.caught121 = 1; await say('CHEDBURN: Look after it, Champion. It looked after me.'); }
    else if (b === 'lose') { await blackout(); return; }
    else await say('Genesite hops back behind Chedburn\'s chair.|CHEDBURN: It\'s not ready yet. Beat the Council again and it\'ll be waiting.');
    saveGame();
  }
  TOWNS.northridge = ['Northridge', 'northridge', 4, 6, 'down'];
