  async function eaglewingTalk(n) {
    if (G.flags.eaglewing) { await say('EAGLEWING: Thanks for playing Tornies, {P}! Seriously.|Now go and catch them all. All ' + DEX_GOAL + '. I\'ll know if you don\'t.'); return; }
    await say('EAGLEWING: Whoa! How did you get in here?! This is the dev room!|...Oh, you guessed the password. From the hospital chart. I really need to stop leaving notes everywhere.');
    await say('EAGLEWING: Hi! I\'m Eaglewing. I made this whole game. The Tornies, the city, the Racket, all of it.|I put this room here for anyone who found every secret. And you found it!');
    await say('EAGLEWING: So... want to battle the person who made the game? I promise I didn\'t give myself cheats.|Mostly.');
    const r = await trainerBattle('eaglewing', { npc: n });
    if (r !== 'win') return;
    G.flags.eaglewing = 1;
    await say('EAGLEWING: Okay, you\'re officially better at my game than I am. That\'s the best feeling ever.|Take this. It\'s the rarest thing in Tornies, after the Federal Capsule.');
    addItem('rankcharm', 1); jingle('badge');
    await say('{P} got the GOLDEN CHARM!|Golden Tornies will appear three times as often!');
    await say('EAGLEWING: Thanks for playing. See you in Torn City.');
    saveGame();
  }

