  // A horizontal route template: 36x14, a road along rows 6-7 and a theme.
  function ringRoute(id, name, bg, base, deco, grass, o) {
    const g = canvasMap(36, 14, base === 'water' ? '~' : '#');
    if (base !== 'water') g.fill(1, 2, 34, 10, bg === 'sand' ? '_' : (bg === 'city' ? 'p' : '.'));
    g.fill(0, 6, 36, 2, o.road || '=');
    (grass || []).forEach(function (q) { g.fill(q[0], q[1], q[2], q[3], ','); });
    (deco || []).forEach(function (q) { g.put(q[1], q[0]); });
    if (o.edit) o.edit(g);
    defMap(id, Object.assign({ name: name, outdoor: true, bg: bg, border: base === 'water' ? '~' : '#', rows: g.rows() }, o.map));
  }
