  /* ================= Trainers use the newer Tornies (122-171) ================= */
  // Each regular trainer may swap one Tornie for a newer one that fits where they stand and how strong they are.
  // Arena Leaders, the rival, the Torn Council, the Champion, Racket bosses and arena trainers keep their teams.
  (function () {
    const SKIP_CLS = ['Arena Leader', 'Rival', 'Torn Council', 'Champion', 'Creator', 'Racket Boss', 'Crime Lord', 'Lieutenant'];
    const RARE = { 164: 1, 165: 1, 166: 1, 167: 1, 168: 1 };
    // Where each trainer stands.
    const home = {};
    Object.keys(MAPS).forEach(function (id) { (MAPS[id].npcs || []).forEach(function (n) { if (n.trainer && !home[n.trainer]) home[n.trainer] = id; }); });
    // Lowest level each new Tornie (or the Tornie it evolves from) can be met at.
    const minLv = {}, onMap = {};
    Object.keys(MAPS).forEach(function (id) {
      const m = MAPS[id];
      [m.wild].concat((m.zones || []).map(function (z) { return z.wild; })).concat([m.fish]).forEach(function (t) {
        (t || []).forEach(function (e) {
          if (e[0] < 122 || RARE[e[0]] || e[0] >= 169) return;
          minLv[e[0]] = Math.min(minLv[e[0]] || 999, e[1]);
          (onMap[id] = onMap[id] || {})[e[0]] = 1;
        });
      });
    });
    function grown(sp, lv) { while (SP[sp].evo && lv >= SP[sp].evo.lv) sp = SP[sp].evo.to; return sp; }
    const used = {};
    function hash(s) { let h = 7; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; return Math.abs(h); }
    Object.keys(TRAINERS).forEach(function (id) {
      const t = TRAINERS[id], map = home[id];
      if (!t.party || !t.party.length || SKIP_CLS.indexOf(t.cls) >= 0 || !map || /^gym_|^arena|council|champion/.test(map)) return;
      // Older Tornies that now have a further evolution grow into it at the right level.
      t.party.forEach(function (e) { if (SP[e[0]].evo && SP[e[0]].evo.to >= 122 && e[1] >= SP[e[0]].evo.lv) e[0] = SP[e[0]].evo.to; });
      const h = hash(id);
      if (h % 10 >= 6) return;                     // about 6 in 10 trainers get a new Tornie
      const lv = t.party[Math.max(0, t.party.length - 2)][1];
      const types = {}; t.party.forEach(function (e) { SP[e[0]].types.forEach(function (ty) { types[ty] = 1; }); });
      const ok = Object.keys(minLv).map(Number).filter(function (sp) { return minLv[sp] <= lv + 2; });
      if (!ok.length) return;
      const here = ok.filter(function (sp) { return onMap[map] && onMap[map][sp]; });
      const same = ok.filter(function (sp) { return SP[sp].types.some(function (ty) { return types[ty]; }); });
      const mix = here.concat(same.filter(function (sp) { return here.indexOf(sp) < 0; })), pool = mix.length ? mix : ok;
      // Spread the picks around: prefer the new Tornie fewest trainers are already using.
      const sorted = pool.slice().sort(function (a, b) { return (used[grown(a, lv)] || 0) - (used[grown(b, lv)] || 0) || ((h + a) % 7) - ((h + b) % 7); });
      const pick = grown(sorted[0], lv);
      used[pick] = (used[pick] || 0) + 1;
      if (t.party.some(function (e) { return e[0] === pick; })) return;
      const slot = t.party.length > 1 ? (h >> 4) % (t.party.length - 1) : 0;   // never the last (strongest) Tornie
      t.party[slot] = [pick, t.party[slot][1]].concat(t.party[slot].slice(2));
    });
  })();

