  /* ================= Anton The Bunnster: a trickster who turns up anywhere and tries to mug you ================= */
  // He can appear on any map at any time (outside arenas and the Torn Council), any number of times.
  // His team is built on the spot to match the player's own team.
  PAL.anton = { h: '#e98bc6', q: '#ffc8e4', c: '#e391c9', p: '#d77fbb', s: '#f3ecec', b: '#f4a6d6', style: 'bunny', glasses: 1, gc: '#ff2f8f' };
  TRAINERS.anton = { cls: 'Trickster', name: 'Anton The Bunnster', pal: 'anton', base: 70, party: [],
    lose: 'Ow! Okay, okay, the slippers stay on. This never happened.',
    winText: 'Hop hop! Pleasure doing business with you!' };
  const ANTON_RATE = 1 / 4000, ANTON_GAP = 1000;        // about once every 5,000 steps on average (1,000-step cooldown + 1 in 4,000 per step)
  const ANTON_POOL = [22, 23, 24, 96, 125, 97, 126, 79, 80, 77, 78, 164, 165, 160, 161, 30, 31, 128, 13, 14, 84, 85, 168];
  const ANTON_HELLO = [
    'Psst! Hey, pal. Nice Tornies. Shame if someone... borrowed your wallet.',
    'Well well well. If it isn\'t my favourite walking piggy bank!',
    'Don\'t mind me. Just a harmless bunny. In sunglasses. Holding your wallet. Wait, that\'s my wallet. Is it?',
    'You look lost! I give directions. Directions cost money. All of your money.',
    'Hop, skip and a mug! Hand over the cash and nobody gets nibbled.',
    'Fancy seeing you here! And here. And here. I get around.'
  ];
  function antonCheck() {
    const m = W.map;
    if (!G.flags.starter || !G.party.some(alive) || W.busy) return false;
    if (/^gym_|^council|^champion|^hof|^lab/.test(m.id)) return false;
    if (G.steps - (G.antonAt || 0) < ANTON_GAP || Math.random() >= ANTON_RATE) return false;
    // He needs somewhere to stand: a free tile one to three steps away, in a straight line from the player.
    const p = W.p;
    for (const dir of ['left', 'right', 'up', 'down'].sort(function () { return Math.random() - 0.5; })) {
      const d = DV[dir];
      for (let k = 3; k >= 1; k--) {
        let clear = true;
        for (let j = 1; j <= k; j++) { const x = p.x + d[0] * j, y = p.y + d[1] * j; if (x < 0 || y < 0 || x >= m.w || y >= m.h || blocked(m, x, y)) clear = false; }
        if (!clear) continue;
        G.antonAt = G.steps;
        const x = p.x + d[0] * k, y = p.y + d[1] * k;
        runScript(function () { return antonMug(x, y, OPP[dir], k); });
        return true;
      }
    }
    return false;
  }
  function antonTeam() {
    const lvs = G.party.map(function (mon) { return mon.lv; }).sort(function (a, b) { return b - a; });
    const top = lvs.slice(0, 3), lv = Math.max(3, Math.round(top.reduce(function (a, b) { return a + b; }, 0) / top.length));
    const n = Math.max(2, Math.min(6, G.party.length));
    const pick = ANTON_POOL.slice().sort(function () { return Math.random() - 0.5; });
    const team = [];
    for (let i = 0; i < pick.length && team.length < n; i++) {
      let sp = pick[i];
      // Use the right stage for the level, so a low-level team never meets a final evolution.
      while (SP[sp].evo && lv >= SP[sp].evo.lv) sp = SP[sp].evo.to;
      if (!team.some(function (t) { return t[0] === sp; })) team.push([sp, Math.max(2, lv + (team.length === n - 1 ? 1 : -1 + (i % 2)))]);
    }
    return team;
  }
  async function antonMug(x, y, dir, dist) {
    const n = { def: { id: 'anton', pal: 'anton', trainer: 'anton' }, id: 'anton', x: x, y: y, ox: x, oy: y, dir: dir, moving: false, t: 0, tx: x, ty: y, step: 0, wait: 99, res: null };
    W.npcs.push(n);
    W.alert = n; tone(880, 0.07, 'square', 0.05); setTimeout(function () { tone(1320, 0.12, 'square', 0.05); }, 80);
    await wait(0.7); W.alert = null;
    for (let k = 1; k < dist; k++) await npcStep(n, dir);
    W.p.dir = OPP[dir];
    G.anton = G.anton || { met: 0, won: 0 };
    G.anton.met++;
    await say('ANTON THE BUNNSTER: ' + (G.anton.met === 1 ? 'Hello there! The name\'s Anton. Anton The Bunnster. Don\'t wear it out.|Now, about that wallet of yours...' : ANTON_HELLO[Math.floor(Math.random() * ANTON_HELLO.length)]));
    const r = await trainerBattle('anton', { party: antonTeam() });
    if (r === 'win') {
      G.anton.won++;
      await say('ANTON THE BUNNSTER: You haven\'t seen the last of me! I\'m everywhere! I\'m the floor! I\'m the ceiling!');
      await say('He hops away in a puff of pink fluff.');
      // Sometimes he drops something he "found" earlier.
      if (Math.random() < 0.4) {
        const drugs = Object.keys(BOOSTERS).filter(function (k) { return k !== 'vicodin' && k !== 'xanax'; });
        const common = ['hyper_potion', 'hyper_potion', 'capsule3', 'capsule3', 'revive', 'full_heal', 'xanax'];
        const it = Math.random() < 0.85 ? common[Math.floor(Math.random() * common.length)] : drugs[Math.floor(Math.random() * drugs.length)];
        addItem(it, 1); jingle('item');
        await say('Anton dropped something as he fled!|{P} found ' + (BOOSTERS[it] ? 'some ' : 'a ') + ITEMS[it].name + '!');
      }
    }
    removeNpc('anton');
    saveGame();
  }

  /* ================= Weather ================= */
  // Outdoor maps share weather by climate. It changes every 3 hours of Torn City Time and is worked out from the clock,
  // so every player sees the same weather at the same time. Indoors is always clear.
  const WEATHER = {
    clear: { name: 'Clear' },
    rain:  { name: 'Rain', icon: '☔', start: 'Rain is pouring down! Water moves are stronger and Fire moves are weaker.', boost: { Water: 1.5, Fire: 0.5 }, spawn: ['Water'] },
    snow:  { name: 'Snow', icon: '❄', start: 'Snow is falling! Ice moves are stronger.', boost: { Ice: 1.5 }, spawn: ['Ice'] },
    fog:   { name: 'Fog', icon: '☁', start: 'A thick fog hangs in the air. Spirit and Shadow moves are stronger.', boost: { Spirit: 1.3, Shadow: 1.3 }, spawn: ['Spirit', 'Shadow'] }
  };
  const COAST = { docks: 1, route4: 1, route5: 1, route6: 1, route11: 1, route14: 1, route24: 1, isles: 1, jungle: 1, route22: 1, route25: 1 };
  const MISTY = { hospdist: 1, route13: 1, forest: 1, reserve: 1 };
  const DRY = { route20: 1, route21: 1, casino: 1 };
  function climateOf(m) {
    if (m.bg === 'snow') return ['snow', ['snow', 'snow', 'snow', 'clear', 'fog']];
    if (COAST[m.id]) return ['coast', ['rain', 'rain', 'clear', 'clear', 'fog']];
    if (MISTY[m.id]) return ['misty', ['fog', 'fog', 'clear', 'rain']];
    if (DRY[m.id]) return ['dry', ['clear', 'clear', 'clear', 'clear', 'fog']];
    return ['city', ['clear', 'clear', 'clear', 'rain', 'fog']];
  }
  let forceWeather = null;
  function weatherNow(m) {
    m = m || W.map;
    if (!m || m.indoor || !m.outdoor) return 'clear';
    if (forceWeather) return forceWeather;
    const c = climateOf(m), d = new Date(), slot = d.getUTCFullYear() * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate() + Math.floor(d.getUTCHours() / 3) / 10;
    let h = 2166136261;
    const key = c[0] + slot;
    for (let i = 0; i < key.length; i++) { h ^= key.charCodeAt(i); h = Math.imul(h, 16777619); }
    return c[1][(h >>> 0) % c[1].length];
  }
  function weatherMul(type) { const w = B && WEATHER[B.weather]; return (w && w.boost && w.boost[type]) || 1; }
  // Weather draws over the world and battle screens.
  function drawWeather(w, dx, dy) {
    if (w === 'rain') {
      fr(0, 0, VW, VH, 'rgba(40,60,90,0.18)');
      ctx.strokeStyle = 'rgba(200,220,255,0.55)'; ctx.lineWidth = 1; ctx.beginPath();
      for (let i = 0; i < 70; i++) {
        const sx = (i * 53.7 + T * 40) % (VW + 40) - 20, sy = ((i * 97.3) + T * 260) % (VH + 20) - 10;
        const x = ((sx - (dx || 0) * 0.3) % (VW + 40) + VW + 40) % (VW + 40) - 20, y = ((sy - (dy || 0) * 0.3) % (VH + 20) + VH + 20) % (VH + 20) - 10;
        ctx.moveTo(x, y); ctx.lineTo(x - 3, y + 8);
      }
      ctx.stroke();
    } else if (w === 'snow') {
      fr(0, 0, VW, VH, 'rgba(220,235,255,0.10)');
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      for (let i = 0; i < 60; i++) {
        const sp = 14 + (i % 5) * 4, x0 = (i * 61.3) % VW, y0 = (i * 37.1) % VH;
        const x = ((x0 + Math.sin(T * 1.3 + i) * 6 - (dx || 0) * 0.3) % VW + VW) % VW, y = ((y0 + T * sp - (dy || 0) * 0.3) % VH + VH) % VH;
        ctx.fillRect(x, y, i % 3 ? 1 : 2, i % 3 ? 1 : 2);
      }
    } else if (w === 'fog') {
      // Soft drifting banks of mist.
      for (let k = 0; k < 7; k++) {
        const x = (((k * 83 + T * (5 + k % 3 * 2) - (dx || 0) * 0.2) % (VW + 140)) + VW + 140) % (VW + 140) - 70, y = 10 + (k * 47) % (VH - 10);
        const gr = ctx.createRadialGradient(x, y, 4, x, y, 70);
        gr.addColorStop(0, 'rgba(232,236,242,0.32)'); gr.addColorStop(1, 'rgba(232,236,242,0)');
        ctx.fillStyle = gr; ctx.fillRect(x - 70, y - 70, 140, 140);
      }
      fr(0, 0, VW, VH, 'rgba(220,226,232,0.16)');
    }
  }
  // Wild Tornies that like the weather turn up twice as often.
  function weatherSpawns(list) {
    const w = WEATHER[weatherNow(W.map)];
    if (!w || !w.spawn) return list;
    return list.map(function (e) { return SP[e[0]].types.some(function (t) { return w.spawn.indexOf(t) >= 0; }) ? [e[0], e[1], e[2], e[3] * 2, e[4]] : e; });
  }

