      o.type = 'sine'; o.frequency.setValueAtTime(140, at); o.frequency.exponentialRampToValueAtTime(42, at + 0.11);
      g.gain.setValueAtTime(0, at); g.gain.linearRampToValueAtTime(0.26, at + 0.004); g.gain.setTargetAtTime(0, at + 0.03, 0.04);
      o.connect(g); g.connect(out); o.start(at); o.stop(at + 0.3);
