    f.type = k === 's' ? 'bandpass' : 'highpass'; f.frequency.value = k === 's' ? 1800 : 7000; if (k === 's') f.Q.value = 0.7;
    g.gain.setValueAtTime(0, at); g.gain.linearRampToValueAtTime(vol, at + 0.003); g.gain.setTargetAtTime(0, at + 0.003, len / 2.5);
