      d.delayTime.value = (30 / s.bpm) * 1.5; fb.gain.value = 0.32; wet.gain.value = s.echo; dl.type = 'lowpass'; dl.frequency.value = 2400;
      send.connect(master); send.connect(d); d.connect(dl); dl.connect(fb); fb.connect(d); dl.connect(wet); wet.connect(master);
