  Object.keys(ITEMS).forEach(function (id) { const it = ITEMS[id]; if (it.kind === 'disc' && it.desc.indexOf('Single use') < 0) it.desc += ' Single use.'; });
  function fieldCanLearn(mon, id) { return SP[mon.sp].allDiscs || FIELD[id].types.some(function (t) { return SP[mon.sp].types.indexOf(t) >= 0; }) || SP[mon.sp].learn.some(function (l) { return l[1] === FIELD[id].move; }); }
  // Who can use a field move right now: the Field Disc is in the bag and a healthy team member knows the move.
  function fieldUser(id) {
    if (!G.bag[id]) return null;
    return G.party.find(function (m) { return m.hp > 0 && m.moves.some(function (x) { return x.id === FIELD[id].move; }); }) || null;
  }
  async function fieldDiscGift(medal, who) {
    const id = Object.keys(FIELD).find(function (k) { return FIELD[k].medal === medal; });
    if (!id || G.bag[id]) return;
    addItem(id, 1); jingle('item');
    await say((who ? who + ': ' : '') + 'One more thing. This Field Disc teaches ' + MOVES[FIELD[id].move].name + '.|' + FIELD[id].use + ' It never runs out, so teach it to as many Tornies as you like.');
    await say('{P} got ' + ITEMS[id].name + '!');
  }
  // Older saves: hand over the discs for medals already won.
  function fieldDiscCatchUp() { Object.keys(FIELD).forEach(function (id) { if (G.badges.indexOf(FIELD[id].medal) >= 0 && !G.bag[id]) G.bag[id] = 1; }); }

  // Map changes (pushed or smashed boulders) are stored per tile.
  function ovKey(m, x, y) { return m.id + ':' + x + ',' + y; }
  function ovTile(m, x, y) { return G && G.ov ? G.ov[ovKey(m, x, y)] : undefined; }
  function setOv(m, x, y, ch) { G.ov = G.ov || {}; G.ov[ovKey(m, x, y)] = ch; }
  function floorOf(m) { return m.indoor ? (m.tiles || 'o') : m.bg === 'city' || m.bg === 'docks' || m.bg === 'neon' ? 'p' : m.bg === 'snow' ? '*' : m.bg === 'sand' ? '_' : m.cave ? 'C' : '.'; }

  // Pressing A on water or a boulder.
  function fieldCheck(t, x, y) {
    const m = W.map;
    if (t === '~' && !G.surf && fieldUser('field_surf')) { runScript(function () { return surfStart(x, y); }); return true; }
    if (t === 'R' && !/^gym_|^council|^champion/.test(m.id) && (fieldUser('field_smash') || fieldUser('field_lift'))) { runScript(function () { return boulderAct(x, y); }); return true; }
    return false;
  }
  async function surfStart(x, y) {
    const mon = fieldUser('field_surf');
    const c = await say('The water is calm. ' + monName(mon) + ' could carry you across.', { hold: true });
    const opts = ['RIDE THE WAVES'].concat(W.map.fish && hasRod() ? ['FISH'] : []).concat(['CANCEL']);
    const i = await menu(opts, { x: VW - 120, y: VH - 96, w: 116 });
    pop(c);
    if (opts[i] === 'FISH') { await fishHere(); return; }
    if (opts[i] !== 'RIDE THE WAVES') return;
    await say(monName(mon) + ' used ' + MOVES.wave_rider.name + '!');
    G.surf = 1; jingle('item');
    await stepTo(x, y);
  }
  // Walk the player onto the next tile (used to hop onto the water).
  function stepTo(x, y) { return new Promise(function (res) { startMove(x, y); const iv = setInterval(function () { if (!W.p.moving) { clearInterval(iv); res(); } }, 30); }); }
  async function boulderAct(x, y) {
    const smash = fieldUser('field_smash'), lift = fieldUser('field_lift'), d = DV[W.p.dir], nx = x + d[0], ny = y + d[1], m = W.map;
    const canPush = lift && nx >= 0 && ny >= 0 && nx < m.w && ny < m.h && !blocked(m, nx, ny) && !isSpecial(m, nx, ny) && tileAt(m, nx, ny) !== '~';
    const opts = [];
    if (lift) opts.push('PUSH IT');
    if (smash) opts.push('SMASH IT');
    opts.push('CANCEL');
    const c = await say('A huge boulder blocks the way.', { hold: true });
    const i = await menu(opts, { x: VW - 104, y: VH - 96, w: 100 });
    pop(c);
    if (opts[i] === 'PUSH IT') {
      if (!canPush) { await say(monName(lift) + ' strains, but the boulder won\'t move that way. Something is in the way.'); return; }
      await say(monName(lift) + ' used ' + MOVES.heavy_lift.name + '!');
      tone(110, 0.35, 'sawtooth', 0.05, 70);
      setOv(m, x, y, floorOf(m)); setOv(m, nx, ny, 'R');
      saveGame();
    } else if (opts[i] === 'SMASH IT') {
      await say(monName(smash) + ' used ' + MOVES.rock_smash.name + '!');
      seq([[0, 180, 0.08, 'square', 0.06], [70, 120, 0.12, 'sawtooth', 0.05]]);
      setOv(m, x, y, floorOf(m));
      saveGame();
      const r = Math.random();
      if (r < 0.15) { const it = ['potion', 'super_potion', 'capsule2', 'energy_bar'][Math.floor(Math.random() * 4)]; addItem(it, 1); jingle('item'); await say('Something was buried under the boulder!|{P} found a ' + ITEMS[it].name + '!'); }
      else if (r < 0.3 && m.wild) { await say('A wild Tornie was hiding under the boulder!'); await wildBattle(); }
    }
  }
  // Called after each step: get off the water when you reach land, and meet water Tornies while riding the waves.
  function surfStep(m, here) {
    if (!G.surf) return false;
    if (here !== '~') { G.surf = 0; return false; }
    if (m.fish && !G.repel && G.party.some(alive) && Math.random() < 0.06) { runScript(function () { return wildBattle(m.fish); }); return true; }
    return false;
  }
  // The rider: a little surfboard under the player while on the water.
