    if (!G.surf) return;
    const bob = Math.sin(T * 4) * 0.8;
    ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.fillRect(sx - 1, sy + 13 + bob, 18, 2);
    ctx.fillStyle = '#e8743a'; ctx.fillRect(sx + 1, sy + 10 + bob, 14, 4);
