  (function () {
    function hash(s) { let h = 17; for (let i = 0; i < s.length; i++) h = (h * 33 + s.charCodeAt(i)) | 0; return Math.abs(h); }
    // Trainers: about two in three of each class get one of the new looks that fits their job.
    const BY_CLASS = { 'Punk': ['mohawk'], 'Biker': ['racer', 'mohawk'], 'Gambler': ['magician'], 'High Roller': ['magician'], 'Dealer': ['magician', 'office'],
      'Boxer': ['fighter'], 'Student': ['scholar', 'hacker'], 'Engineer': ['builder', 'hacker'], 'Worker': ['builder'], 'Welder': ['builder'], 'Scrapper': ['builder'],
      'Fisher': ['seadog'], 'Sailor': ['seadog'], 'Lady': ['exec'], 'Gent': ['office'], 'Jogger': ['jogger'], 'Cyclist': ['jogger', 'racer'],
      'Racket Thug': ['bouncer', 'mohawk', 'racer'], 'Researcher': ['hacker'], 'Islander': ['disco'], 'Rookie': ['rookie', 'casual', 'blonde'], 'Veteran': ['fighter', 'seadog', 'jogger'] };
    const npcOf = {};
    Object.keys(MAPS).forEach(function (id) { (MAPS[id].npcs || []).forEach(function (n) { if (n.trainer) npcOf[n.trainer] = n; }); });
    Object.keys(TRAINERS).forEach(function (id) {
      const t = TRAINERS[id], looks = BY_CLASS[t.cls], h = hash(id);
      if (!looks || h % 3 === 0) return;
      const look = looks[h % looks.length];
      t.pal = look;
      if (npcOf[id]) npcOf[id].pal = look;
    });
    // Everyday people: about one in four plain townsfolk gets a new look.
    const TOWNSFOLK = { man: ['office', 'bouncer', 'hacker', 'racer', 'jogger', 'chef', 'disco'], woman: ['exec', 'jogger', 'scholar', 'disco'], rookie: ['hacker', 'jogger'], punk: ['mohawk'], worker: ['builder'], fisher: ['seadog'], sailor: ['seadog'], gent: ['office', 'magician'] };
    Object.keys(MAPS).forEach(function (id) {
      (MAPS[id].npcs || []).forEach(function (n) {
        if (n.trainer || n.kind || !TOWNSFOLK[n.pal] || !n.id) return;
        const h = hash(n.id);
        if (h % 4 !== 1) return;
        const looks = TOWNSFOLK[n.pal];
        n.pal = looks[h % looks.length];
      });
    });
  })();

  /* ================= Secret places: the Private Island and the City Dump ================= */
  PAL.clansdancer = { h: '#6a2a7a', c: '#c83040', p: '#f4f4f4', b: '#c83040', style: 'long', x: ['stripes'], q: '#ffffff', glasses: 0 };

  /* --- 1. The Private Island (off the Coral Isles). Old Pete rows you over. -Clansdancer is waiting inside. --- */
  defMap('private_island', {
    name: 'Private Island Villa', bg: 'indoor', border: 'w', indoor: true, tiles: 'o', banner: 1,
    rows: ['wwwwwwwwwwww', 'wwwwwwwwwwww', 'BBoTooAoDDog', 'oooooooooooo', 'oLLooooo~~~o', 'oLLooooo~~~o', 'oooooooooooo', 'goooooooooog', 'ooooommooooo'],
    warps: mats([5, 6], 8, 'isles', 4, 10),
    things: {
      B: 'Shelves of old Torn City Times. The newest one is dated 30 November 2016. The headline: "CHRISTMAS TOWN OPENS TOMORROW!"',
      T: 'A big TV, still switched on. It\'s been showing the same Torn City news loop since 2016. Nobody has changed the channel.',
      A: 'A calendar stuck on DECEMBER 2016. The 1st is circled in red pen: "Christmas Town!!! Do NOT fall asleep."',
      D: 'A huge bed. The sheets are covered in a thick layer of dust.',
      L: 'A glass coffee table. On it is a plushie set laid out in a row: twelve plushies and one empty space where the Lion should be.',
      g: 'A potted palm. Somehow it\'s still alive after all these years. Torn City plants are tough.'
    },
    acts: [[1, 4, function () { return say('A note in neat handwriting:|"Gone to Christmas Town. Back in 5 minutes. -C"|...The ink is still wet.'); }, function () { return !!G.flags.clans; }]],
    npcs: [{ id: 'clansdancer', x: 6, y: 5, dir: 'down', pal: 'clansdancer', move: 'still', cond: function () { return !G.flags.clans; }, run: clansdancerTalk }]
  });
  // Old Pete and his rowing boat on the west shore of the Coral Isles.
