  if (!PAL.clerk) PAL.clerk = PAL.man;

  async function btowerDesk() {
    const t = towerState();
    if (!G.flags.champion) { await say('RECEPTIONIST: Welcome to the Battle Tower! I\'m afraid only the Champion of Torn City may take the challenge.|Beat the Torn Council and Chedburn, then come back and see me.'); return; }
    if (t.paused) {
      const ok = await yesno('RECEPTIONIST: Welcome back! You were on a ' + t.streak + '-win streak. Carry on where you left off?');
      if (ok) {
        const team = t.paused.map(function (uid) { return G.party.concat(G.box).find(function (m) { return m.uid === uid; }); });
        if (team.some(function (m) { return !m; })) { await say('RECEPTIONIST: Oh dear. One of the Tornies from that team isn\'t with you any more. I\'m afraid your streak has ended.'); t.paused = null; t.streak = 0; saveGame(); return; }
        t.paused = null;
        await runTower(team);
        return;
      }
      if (!(await yesno('RECEPTIONIST: Do you want to give up your streak of ' + t.streak + ' and start again?'))) return;
      t.paused = null; t.streak = 0;
    }
    await say('RECEPTIONIST: Welcome to the Battle Tower, Champion!');
    while (true) {
      const c = await menu(['CHALLENGE', 'RULES', 'RECORDS', 'BYE'], { x: 4, y: 4, w: 100 });
      if (c === 0) {
        const ok = G.party.filter(towerEligible);
        if (ok.length < 3) { await say('RECEPTIONIST: You need three Tornies in your team to enter. Legendary Tornies aren\'t allowed, I\'m afraid.'); continue; }
        const team = [];
        while (team.length < 3) {
          const i = await partyScreen({ pick: true, prompt: 'Choose Tornie ' + (team.length + 1) + ' of 3' });
          if (i === null) { team.length = 0; break; }
          const m = G.party[i];
          if (!towerEligible(m)) { await say('RECEPTIONIST: Legendary Tornies can\'t enter the Battle Tower.'); continue; }
          if (team.indexOf(m) >= 0) { await say(monName(m) + ' is already on your team.'); continue; }
          if (team.some(function (x) { return x.sp === m.sp; })) { await say('RECEPTIONIST: Only one of each kind of Tornie, please.'); continue; }
          team.push(m);
        }
        if (team.length < 3) continue;
        if (!(await yesno('Enter with ' + team.map(monName).join(', ') + '? They\'ll all fight at level 50.'))) continue;
        t.streak = 0;
        await runTower(team);
        return;
      } else if (c === 1) {
        await say('RECEPTIONIST: Bring three Tornies. No Legendaries, and no two the same.|Everyone fights at level 50, so the best-trained team wins, not the highest level.|You can\'t use items, but your team is fully healed after every battle.');
        await say('RECEPTIONIST: Each win earns Battle Points. The longer your streak, the more BP each win is worth, with a bonus every seventh win.|Spend BP at the Prize Counter. And at 21 and 49 wins in a row... well. You\'ll see.');
      } else if (c === 2) {
        await say('RECEPTIONIST: Your best streak is ' + t.best + '. You\'ve won ' + t.wins + ' Tower battles in total and you have ' + (t.bp || 0) + ' BP.' + (t.gold ? '|You hold the GOLD PRINT. Duke talks about you a lot.' : t.silver ? '|You hold the SILVER PRINT.' : ''));
      } else { await say('RECEPTIONIST: We hope to see you again!'); return; }
    }
  }
  async function runTower(team) {
    const t = towerState();
    t.runs = (t.runs || 0) + 1;
    G.towerReal = G.party;
    G.party = team.map(at50);
    const uids = team.map(function (m) { return m.uid; });
    let ended = 'retire';
    await fadeOut(0.4);
    loadMap('btower_room', 3, 4, 'right');
    await fadeIn(0.4);
    try {
      while (true) {
        const n = t.streak + 1, T0 = twTrainer(n), party = T0.boss ? dukeTeam(T0.boss === 'gold') : twTeam(n);
        await say(T0.boss ? 'Battle ' + n + '. The lights dim... and the Tower Tycoon walks in.' : 'Battle ' + n + '. Your opponent is entering the room...');
        const opp = { def: { id: 'tw_opp', pal: T0.pal }, id: 'tw_opp', x: 8, y: 4, ox: 8, oy: 4, dir: 'left', moving: false, t: 0, tx: 8, ty: 4, step: 0, wait: 99, res: null };
        W.npcs.push(opp);
        await npcStep(opp, 'left'); await npcStep(opp, 'left');
        if (T0.boss) await say(T0.boss === 'gold' ? 'DUKE: Forty-eight wins. You know what that means? It means I stop holding back.|Everything I have. Right now.' : 'DUKE: Twenty wins in a row? In MY tower?|I\'m Duke. I built this place. Let\'s see what you\'re made of.');
        else await say(T0.cls.toUpperCase() + ' ' + T0.name.toUpperCase() + ': ' + T0.hello);
        const r = await battle({ trainer: T0, tid: 'tower', party: party, noBlackout: true, tower: true });
        removeNpc('tw_opp');
        if (r !== 'win') { ended = 'lose'; break; }
        t.streak = n; t.best = Math.max(t.best, n); t.wins++;
        const bp = twBP(n) + (T0.boss ? (T0.boss === 'gold' ? 50 : 20) : 0);
        t.bp = (t.bp || 0) + bp; gstat('towerWins');
        jingle('item');
        await say('That\'s ' + n + ' win' + (n > 1 ? 's' : '') + ' in a row! {P} earned ' + bp + ' BP.' + (n % 7 === 0 ? '|A seventh win! That includes a 5 BP bonus.' : ''));
        if (T0.boss === 'silver' && !t.silver) { t.silver = 1; addItem('print_silver', 1); jingle('badge'); await say('{P} received the SILVER PRINT from Duke!'); }
        if (T0.boss === 'gold' && !t.gold) { t.gold = 1; addItem('print_gold', 1); jingle('badge'); await say('{P} received the GOLD PRINT from Duke!|DUKE: Put that somewhere everyone can see it.'); }
        checkMerits();
        healParty();
        await say('Your team was patched up and is ready to go.');
        const next = n + 1, c = await ask('Next is battle ' + next + (next === 21 || next === 49 ? '. Duke is waiting...' : '.'), ['CONTINUE', 'TAKE A BREAK', 'RETIRE']);
        if (c === 1) { ended = 'break'; break; }
        if (c === 2 || c < 0) { ended = 'retire'; break; }
        saveGame();
      }
    } finally {
      G.party = G.towerReal; delete G.towerReal;
    }
    await fadeOut(0.4);
    loadMap('btower', 5, 4, 'up');
    await fadeIn(0.4);
    if (ended === 'lose') { await say('RECEPTIONIST: Bad luck! Your streak ended at ' + t.streak + '.|Your best ever is ' + t.best + '. Come back and beat it!'); t.streak = 0; }
    else if (ended === 'break') { t.paused = uids; await say('RECEPTIONIST: Your streak of ' + t.streak + ' has been saved. Come back to me when you\'re ready to carry on.'); }
    else { await say('RECEPTIONIST: You retired with a streak of ' + t.streak + '. Well fought!'); t.streak = 0; }
    await say('RECEPTIONIST: You have ' + t.bp + ' BP to spend at the Prize Counter.');
    checkMerits();
    saveGame();
  }
  // The Prize Counter: Battle Points for rare items.
