    '.ti-title b{display:block;font-size:13px;letter-spacing:.6px;color:#7dff8a;line-height:1.15}',
    '.ti-title small{display:block;font-size:10.5px;color:var(--muted)}',
    '.ti-wide .ti-field{justify-content:space-between}',
