  let CW = 960, CH = 540, dpr = 1;
  function fit() {
    // Layout sizes (not getBoundingClientRect): the phone may be mid-rotation, which is only a transform.
    const pw = root.clientWidth, ph = root.clientHeight;
    if (pw < 20 || ph < 20) return;
    root.classList.toggle('ti-wide', pw > ph * 1.2);
    const r = { width: stageEl.clientWidth, height: stageEl.clientHeight };
    let w = Math.max(160, r.width), h = Math.max(90, r.height);
    if (w / h > 16 / 9) w = h * 16 / 9; else h = w * 9 / 16;
    CW = Math.floor(w); CH = Math.floor(h); dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.style.width = CW + 'px'; canvas.style.height = CH + 'px';
    canvas.width = Math.round(CW * dpr); canvas.height = Math.round(CH * dpr);
  }

  /* ================= Game state ================= */
  let level = 0, MW = 0, MH = 0, grid = null, BG = null;
  let player = null, enemies = [], items = [], barrels = [], shots = [], fx = [], exitPad = null;
