    txt('SCORE ' + runScore, CW - 16 * s, 20 * s, 13 * s, '#ffd65a', 'right', 800);
    let msgY = 54 * s;
    if (boss && !boss.dead && boss.awake) {
      const bw = Math.min(CW * 0.5, 420 * s), bx = (CW - bw) / 2, by = 40 * s;
      txt('ALIEN QUEEN', CW / 2, by - 6 * s, 12 * s, '#e2bbff', 'center', 900);
      roundRect(ctx, bx, by, bw, 10 * s, 5 * s); ctx.fillStyle = 'rgba(0,0,0,.6)'; ctx.fill();
      roundRect(ctx, bx, by, Math.max(2, bw * boss.hp / boss.maxHp), 10 * s, 5 * s); ctx.fillStyle = '#b24ad6'; ctx.fill();
      ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(226,187,255,.6)'; roundRect(ctx, bx, by, bw, 10 * s, 5 * s); ctx.stroke();
      msgY = 74 * s;
    }
    if (msgT > 0) { ctx.globalAlpha = Math.min(1, msgT); txt(msg, CW / 2, msgY, 16 * s, '#ffffff', 'center', 800); ctx.globalAlpha = 1; }
    // damage direction
    dmgDirs.forEach(function (d) {
      const a = d.a - player.a - Math.PI / 2;
      ctx.strokeStyle = 'rgba(255,60,40,' + (d.t * 0.85).toFixed(3) + ')'; ctx.lineWidth = 7 * s;
      ctx.beginPath(); ctx.arc(CW / 2, CH / 2, 74 * s, a - 0.38, a + 0.38); ctx.stroke();
    });
