      txt((practice ? 'Practice run — ' : 'You killed the Alien Queen and cleared all eight levels on ') + (practice ? 'best score not saved.' : diff.name + '.'), CW / 2, CH * 0.26 + 46 * s, 16 * s, '#dfe8f3', 'center', 600);
      txt('FINAL SCORE ' + runScore, CW / 2, CH * 0.26 + 100 * s, 34 * s, '#ffd65a', 'center', 900);
      if (newBest) txt('NEW BEST!', CW / 2, CH * 0.26 + 142 * s, 20 * s, '#ff8a5a', 'center', 900);
