      ot('Bogie versus the Racket', W / 2, 98, 17, '#ffffff');
      drawBogie(130 / S, 66 / S, 0.75, -0.2, 'classic', 0.3, true); drawThug({ x: (W - 130) / S, y: 66 / S, r: 0.7, a: 0.15, type: 'boss', hp: 1, maxHp: 1, seed: 0.3, hurtT: 0 });
