        ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.45)'; ctx.shadowBlur = 12; roundRect(ctx, x, y0, cw, ch, 12); ctx.fillStyle = open ? '#fbe8c4' : '#6a6a72'; ctx.fill(); ctx.restore();
